   &finally; ブロックと、&try; ブロック内で呼び出された exit の相互作用


<?php
try {
    echo 'quit';
    exit(0);
} finally {
    echo 'finally';
}


   &example.outputs;


quit

   &finally; ブロックと、&catch; ブロック内で呼び出された exit の相互作用


<?php
try {
    throw new Exception('foo');
} catch (Exception $e) {
    echo 'catch';
    exit(0);
} finally {
    echo 'finally ';
}


   &example.outputs;


catch

   exit を呼び出すとすべての &finally; ブロックがスキップされる


<?php
try {
    try {
        echo 'quit';
        exit(0);
    } finally {
        echo 'inner finally ';
    }
} finally {
    echo 'outer finally';
}


   &example.outputs;


quit

   exit を呼び出して外側の &finally; ブロックをスキップする


<?php
try {
    try {
        echo 'try', "\n";
    } finally {
        echo 'inner finally ';
        exit(0);
    }
} finally {
    echo 'outer finally';
}


   &example.outputs;


try
inner finally
